(() => {
  const key='proyectat-created-documents-v1';
  let records=[];
  try { const stored=JSON.parse(localStorage.getItem(key)||'[]'); if(Array.isArray(stored))records=stored.filter(d=>d&&typeof d.id==='string'&&typeof d.content==='string'&&typeof d.kind==='string'&&typeof d.updatedAt==='string'&&/^[a-zA-Z0-9-]+$/.test(d.id)); } catch {}
  function save(){try{localStorage.setItem(key,JSON.stringify(records));return true;}catch{toast('No se han podido guardar los documentos. Descárgalos para conservarlos.');return false;}}
  const dialog=document.createElement('dialog');dialog.className='documents-dialog';dialog.setAttribute('aria-labelledby','documents-title');document.body.append(dialog);
  const nav=document.createElement('button');nav.textContent='Documentos creados';nav.onclick=()=>openDocuments();document.querySelector('nav').append(nav);
  function attachAccess(id){const host=$('#workspace');if(host.querySelector('.documents-access'))return;const button=document.createElement('button');button.className='outline documents-access';button.textContent='Documentos creados ('+records.filter(d=>d.opportunityId===id).length+')';button.onclick=()=>{$('#detail-dialog').close();openDocuments(id);};host.append(button);}
  const originalWorkspace=renderWorkspace;
  renderWorkspace=function(id){originalWorkspace(id);attachAccess(id);};
  const originalDetail=showDetail;
  showDetail=function(id){originalDetail(id);attachAccess(id);};
  function draft(x,kind,idea){
    const author=profile.name||'[Tu nombre]';
    const context='Oportunidad: '+x.title+'\nTipo: '+x.type+'\nLugar: '+x.place+'\nPlazo: '+x.deadline+'\nFuente: '+x.url+'\n';
    if(kind==='Propuesta')return 'BORRADOR DE PROPUESTA\n\n'+context+'\nAutoría: '+author+'\n\nIDEA Y OBJETIVO\n'+idea+'\n\nENCAJE CON LA CONVOCATORIA\n'+x.description+'\n[Explica cómo tu idea responde a estas condiciones.]\n\nDESARROLLO Y METODOLOGÍA\n[Describe las actividades, técnicas y fases.]\n\nCALENDARIO\n[Indica fechas y entregables.]\n\nRECURSOS Y PRESUPUESTO\n[Detalla los recursos necesarios y ajusta el presupuesto a las bases.]\n\nRESULTADOS\n[Indica qué presentarás y cómo valorarás el resultado.]\n\nREVISIÓN ANTES DE ENVIAR\n'+x.requirements.map(r=>'□ '+r).join('\n')+'\n\nBorrador editable. Confirma las bases y completa los campos entre corchetes.';
    if(kind==='Carta de presentación')return 'BORRADOR DE CARTA DE PRESENTACIÓN\n\n'+context+'\nA la atención del equipo de selección:\n\nMi nombre es '+author+' y deseo presentar mi candidatura a «'+x.title+'».\n\nMi propuesta parte de la siguiente idea:\n'+idea+'\n\n[Explica tu motivación y la relación de tu trayectoria con esta oportunidad. Incluye solo experiencia acreditable.]\n\n[Resume qué aportarás y señala los documentos que realmente adjuntarás.]\n\nGracias por considerar mi candidatura.\n\n'+author+'\n[Datos de contacto]\n[Fecha]\n\nBorrador pendiente de revisión y adaptación a las bases.';
    return 'LISTA DE REQUISITOS\n\n'+context+'\nIDEA\n'+idea+'\n\nREQUISITOS DOCUMENTADOS EN LA FICHA\n'+x.requirements.map(r=>'□ '+r).join('\n')+'\n\nCOMPROBACIONES ANTES DE PRESENTAR\n□ Consultar las bases vigentes en la fuente enlazada.\n□ Confirmar apertura, hora de cierre y elegibilidad.\n□ Comprobar formato, extensión y documentación obligatoria.\n□ Revisar costes, derechos y condiciones de participación.\n□ Completar y revisar propuesta y carta, si las bases las requieren.\n□ Presentar por el canal oficial y conservar justificante.\n\nEsta lista recoge la ficha disponible; no sustituye las bases completas.';
  }
  function openDocuments(id){
    const x=data.find(o=>o.id===id);
    dialog.innerHTML='<button class="close" aria-label="Cerrar" data-close>×</button><div class="small-label">Mi camino</div><h2 id="documents-title">Documentos creados</h2><p>'+ (x?esc(x?.title||"Oportunidad guardada"):'Borradores vinculados a cada oferta, concurso o convocatoria.')+'</p><div class="document-tabs" role="tablist" aria-label="Documentos"><button role="tab" id="docs-list-tab" aria-controls="docs-panel" aria-selected="true" tabindex="0">Documentos creados</button><button role="tab" id="docs-new-tab" aria-controls="docs-panel" aria-selected="false" tabindex="-1">Crear documentos</button></div><div id="docs-panel" role="tabpanel" aria-labelledby="docs-list-tab"></div><p class="storage-note">Se guardan solo en este navegador. Descárgalos para conservar una copia. Las solicitudes se presentan en la web oficial.</p>';
    const listTab=dialog.querySelector('#docs-list-tab'),newTab=dialog.querySelector('#docs-new-tab');
    function select(create){listTab.setAttribute('aria-selected',!create);newTab.setAttribute('aria-selected',create);listTab.tabIndex=create?-1:0;newTab.tabIndex=create?0:-1;dialog.querySelector('#docs-panel').setAttribute('aria-labelledby',create?'docs-new-tab':'docs-list-tab');if(create)form(id);else list(id);}
    listTab.onclick=()=>select(false);newTab.onclick=()=>select(true);
    [listTab,newTab].forEach(t=>t.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const target=e.key==='Home'?listTab:e.key==='End'?newTab:t===listTab?newTab:listTab;target.focus();select(target===newTab);}});
    select(false);if(!dialog.open)dialog.showModal();
  }
  function list(id){
    const rows=records.filter(d=>id===undefined||d.opportunityId===id);const panel=dialog.querySelector('#docs-panel');
    panel.innerHTML=rows.length?rows.map(d=>{const x=data.find(o=>o.id===d.opportunityId);return '<article class="document-row"><div><h3>'+esc(d.kind)+'</h3><p>'+esc(x?.title||"Oportunidad guardada")+'</p><span class="storage-note">Borrador · '+new Date(d.updatedAt).toLocaleDateString('es-ES')+'</span></div><div class="dialog-actions"><button class="outline" data-preview="'+esc(d.id)+'">Vista previa</button><button class="outline" data-edit="'+esc(d.id)+'">Editar</button><button class="outline" data-download="'+esc(d.id)+'">Descargar Word o PDF</button><button class="detail" data-opportunity="'+(x?.id||d.opportunityId)+'">Ver oportunidad ↗</button></div></article>';}).join(''):'<div class="empty"><h3>Una idea que empieza a tomar forma.</h3><p>Elige una oportunidad y cuenta tu idea para crear la propuesta, la carta y la lista de requisitos.</p><button class="primary" id="first-documents">Crear documentos ↗</button></div>';
    panel.querySelector('#first-documents')?.addEventListener('click',()=>dialog.querySelector('#docs-new-tab').click());
    panel.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(b.dataset.edit,id));
    panel.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const d=records.find(r=>r.id===b.dataset.preview);ProyectaPreview(d.kind,ProyectaExport.text(d.content));});
    panel.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download(b.dataset.download));
    panel.querySelectorAll('[data-opportunity]').forEach(b=>b.onclick=()=>{dialog.close();showDetail(+b.dataset.opportunity);});
  }
  function form(id){
    const panel=dialog.querySelector('#docs-panel');
    panel.innerHTML='<form id="create-documents"><label class="field">Oferta, concurso o convocatoria<select name="opportunity" required>'+data.map(x=>'<option value="'+(x?.id||d.opportunityId)+'" '+(x.id===id?'selected':'')+'>'+esc(x?.title||"Oportunidad guardada")+'</option>').join('')+'</select></label><p id="document-source" class="storage-note"></p><label class="field">Tu idea<textarea class="notes" name="idea" maxlength="6000" required placeholder="Cuenta qué quieres proponer, para quién y qué resultado buscas."></textarea></label><p>Se crearán tres borradores editables: propuesta, carta de presentación y lista de requisitos. Incorporan tu idea y la información de la ficha; tendrás que completar tu trayectoria, calendario y presupuesto.</p><button class="primary" type="submit">Crear y adjuntar los tres documentos ↗</button><p id="document-save-state" role="status"></p></form>';
    const f=panel.querySelector('form');function source(){const x=data.find(o=>o.id===+f.elements.opportunity.value);if(!x)return;panel.querySelector('#document-source').textContent='Estado: '+stateOf(x)+' · Plazo: '+x.deadline;f.elements.idea.value=projects[x.id]?.notes||'';} f.elements.opportunity.onchange=source;source();
    f.onsubmit=e=>{e.preventDefault();const idea=f.elements.idea.value.trim();if(!idea){f.elements.idea.setCustomValidity('Escribe tu idea para crear los documentos.');f.elements.idea.reportValidity();return;}const x=data.find(o=>o.id===+f.elements.opportunity.value);const now=new Date().toISOString();const created=['Propuesta','Carta de presentación','Lista de requisitos'].map((kind,i)=>({id:crypto.randomUUID(),opportunityId:x.id,kind,content:draft(x,kind,idea),updatedAt:now}));records.push(...created);if(!save()){records.splice(-3);panel.querySelector('#document-save-state').textContent='No se han guardado. Libera espacio en el navegador y vuelve a intentarlo.';return;}if(!projects[x.id]&&stateOf(x)==='Abierta'){projects[x.id]={checks:[false,false,false],notes:idea.slice(0,4000)};persist();render();}openDocuments(x.id);toast('Tres documentos creados y vinculados a la oportunidad');};
    f.elements.idea.oninput=()=>f.elements.idea.setCustomValidity('');
  }
  function editor(docId,id){const d=records.find(o=>o.id===docId),panel=dialog.querySelector('#docs-panel');panel.innerHTML='<h3>'+esc(d.kind)+'</h3><label class="field">Contenido del documento<textarea class="notes document-editor" maxlength="30000" id="document-content">'+esc(d.content)+'</textarea></label><p id="document-status" role="status">Puedes editar el borrador y guardar los cambios.</p><div class="dialog-actions"><button class="outline" id="document-preview">Vista previa</button><button class="primary" id="document-save">Guardar cambios</button><button class="outline" id="document-download">Descargar Word o PDF</button><button class="outline" id="document-back">Volver a documentos</button></div>';panel.querySelector('#document-preview').onclick=()=>ProyectaPreview(d.kind,ProyectaExport.text(panel.querySelector('textarea').value));panel.querySelector('#document-save').onclick=()=>{const previous={content:d.content,updatedAt:d.updatedAt};d.content=panel.querySelector('textarea').value;d.updatedAt=new Date().toISOString();if(save())panel.querySelector('#document-status').textContent='Cambios guardados.';else Object.assign(d,previous);};panel.querySelector('#document-download').onclick=()=>{ProyectaExport.choose(d.kind+' - '+(data.find(o=>o.id===d.opportunityId)?.title||'Oportunidad guardada'),ProyectaExport.text(panel.querySelector('textarea').value));};panel.querySelector('#document-back').onclick=()=>list(id);}
  function download(id){const d=records.find(o=>o.id===id),x=data.find(o=>o.id===d.opportunityId);ProyectaExport.choose(d.kind+' - '+(x?.title||'Oportunidad guardada'),ProyectaExport.text(d.content));}
  if(location.hash==='#crear-documentos')openDocuments();
})();
